{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Procainamide, a close structural analogue (para-substituted benzamide with a basic aminoethyl side chain), had absolute oral bioavailability of 79 ± 4% from a sustained-release tablet, directly supporting high F for the query under modified-release conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Procainamide absolute oral bioavailability was 81 ± 13% versus IV, confirming high systemic availability for this benzamide class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Sematilide, another benzamide antiarrhythmic with a basic side chain, had absolute oral bioavailability of about 47%, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Haloperidol, which shares the chlorophenyl and basic amine features, had oral F of 35 ± 8%, supporting high (>20%) bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Loperamide has very low oral bioavailability (0.3%), but its large lipophilic P-gp substrate structure is not shared by the small polar query, so this contradictory evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, polar benzamide with a basic morpholine side chain, closely analogous to procainamide and related benzamides that show absolute oral bioavailability of 46–95%. Modified-release procainamide also shows high F (79%). The only low-F analogue, loperamide, is structurally dissimilar and not transferable. Therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "No human PK data for the query in a modified-release formulation.",
    "First-pass metabolism of the morpholine/amide motif is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

